#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Generate the server's BonkStrings table from the shared i18n catalogue."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

from catalogue import ROOT, load

HEADER = ROOT / "server" / "src" / "game" / "Bonk" / "BonkStrings.h"
SOURCE = ROOT / "server" / "src" / "game" / "Bonk" / "BonkStrings.cpp"

BANNER = (
    "// Generated by tools/i18n/gen_server_strings.py from\n"
    "// shared/i18n/messages/*.yaml. Do not edit by hand.\n"
)


def cpp_string(text: str) -> str:
    escaped = (
        text.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t")
    )
    return f'"{escaped}"'


def enum_name(message_id: str) -> str:
    return "BONK_STRING_" + message_id.removeprefix("hoa.msg.").upper()


def render() -> tuple[bytes, bytes]:
    result = load()
    if result.errors:
        raise SystemExit("i18n errors; run tools/i18n/check.py")
    entries = sorted(
        (entry for entry in result.entries if "legacy_server_id" in entry),
        key=lambda item: item["legacy_server_id"],
    )
    names = [enum_name(entry["id"]) for entry in entries]
    width = max(len(name) for name in names)

    header_lines = [
        BANNER,
        "#ifndef MANGOS_BONKSTRINGS_H",
        "#define MANGOS_BONKSTRINGS_H",
        "",
        '#include "Common.h"',
        "",
        "#include <vector>",
        "",
        "enum BonkString : uint32",
        "{",
    ]
    for name, entry in zip(names, entries):
        header_lines.append(f"    {name:<{width}} = {entry['legacy_server_id']},")
    header_lines += [
        "};",
        "",
        "struct BonkStringText",
        "{",
        "    BonkString id;",
        "    char const* english;",
        "};",
        "",
        "std::vector<BonkStringText> const& GetBonkStringTexts();",
        "",
        "#endif",
        "",
    ]

    source_lines = [
        BANNER,
        '#include "BonkStrings.h"',
        "",
        "std::vector<BonkStringText> const& GetBonkStringTexts()",
        "{",
        "    static std::vector<BonkStringText> const texts =",
        "    {",
    ]
    for name, entry in zip(names, entries):
        source_lines.append(f"        {{ {name + ',':<{width + 1}} {cpp_string(entry['enUS'])} }},")
    source_lines += [
        "    };",
        "    return texts;",
        "}",
        "",
    ]

    return (
        "\n".join(header_lines).encode("utf-8"),
        "\n".join(source_lines).encode("utf-8"),
    )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true", help="fail if the server files differ")
    args = parser.parse_args()
    header, source = render()
    if args.check:
        current_header = HEADER.read_bytes() if HEADER.exists() else b""
        current_source = SOURCE.read_bytes() if SOURCE.exists() else b""
        if current_header != header or current_source != source:
            print("server BonkStrings files are out of date; run tools/i18n/gen_server_strings.py")
            return 1
        print("server BonkStrings: generated from the shared catalogue")
        return 0
    HEADER.write_bytes(header)
    SOURCE.write_bytes(source)
    print(f"wrote {HEADER.relative_to(ROOT)} and {SOURCE.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
